//@name simcore
//@api 3.0
//@version 1.7.0
//@display-name SimCore (시뮬 엔진) v1.7.0 하루 넘김 대리 정산
//@arg aux_model_mode string auto=환경 자동 판별(기본, 권장) / aux=직접 호출 강제 / lua=루아 브리지 강제 / off=상태 자동갱신 끄기
//@arg module_assets string off=모듈 에셋 안 읽음(기본, 빠름) / on=활성 모듈의 추가 에셋까지 읽음(이미지가 모듈에 사는 봇용, 느림)
//
// SimCore 리스 어댑터 — 코어(core/*)는 빌드 시 이 파일 위에 번들됨.
// 빌드: node build.js → dist/simcore.plugin.js
//
// ⚠ [live-test] 표시 지점은 웹리스에서 실제 배선 확인이 필요한 부분.
//
// ── v1.5.4 ────────────────────────────────────────────────
// **에셋 태그 공백 사고** (실기 제보: "에셋이 안 나온다" — 원인 댓글 "띄어쓰기 칸수"가 정답):
// sep=' '(공백 구분) 팩의 주입문 포맷 줄이 slots를 ` ${sep} `로 이어 "who   outfit   [emo]"
// — **세 칸짜리 본보기**가 됐고, 모델이 충실히 베껴 <img="Lim Seol-hee   underwear   default">를
// 썼다. 에셋 이름은 한 칸("Go Eun-bi Casual clothes 2-1 scared")이라 대조가 통째로 죽는다.
// 얼헌 팩 5종 전부 sep=' '라 전부 해당. 두 곳 수리:
// - [core/assets] 포맷 줄 구분자 패딩은 sep이 보이는 문자일 때만 — 공백 sep은 그대로 잇는다.
// - [어댑터 display] <img="…">/<mimg="…"> 안의 연속 공백을 한 칸으로 정규화 — 이미 저장된
//   과거 메시지와, 제 출력을 본보기 삼는 미래분까지 렌더에서 받는다. 저장본은 안 고친다
//   (output 훅 스트리밍 판정이 저장본과의 문자열 일치를 전제 — 건드리면 마커가 밀린다).
//
// ── v1.5.3 ────────────────────────────────────────────────
// **얼헌 "서사가 혼자 날아간다"의 진짜 뿌리** (유저 지적으로 규명): 얼헌 스키마에
// promptState.template이 통째로 비어 있었다 — 즉 메인 모델이 날짜·시각·위치·소지금을
// **하나도 못 보는 채로** 쓰고 있었다. 지금 언제 어디인지 모르니 앵커가 있을 수 없다.
// 값이 모델에 닿는 길은 이 칸 하나뿐인데(상태창 HTML은 display 훅 산물이라 저장도 전송도
// 안 되고, 채팅 변수 미러 chat.scriptstate는 CBS로 불러 써야 프롬프트에 든다 — 얼헌은
// 이식 때 원본 CBS를 전부 구워서 읽는 곳이 0개, ⚙simcore 로어북은 key '__simcore_never__'
// +alwaysActive:false로 절대 안 뜨는 보관함), 이식 봇이라 그 칸만 빈 채로 배포됐다.
// - 검증 경고 신설: statusUI가 있고 (변수 6개+ 또는 시간 체계)인데 promptState.template이
//   없으면 warn. 내장 템플릿 16종은 16/16이 채우므로 조용하고, 장난감 스키마도 문턱 아래다.
// - 얼헌: 300자 상태 블록 신설 (원본 always-on 로어북 6.7K자가 하던 일 — 토큰 이득은 유지).
// v1.5.0 장면 앵커(산문 규칙)는 이 정보 공급이 없으면 반쪽이었다. 규칙 이전에 시계였다.
//
// ── v1.5.2 ────────────────────────────────────────────────
// 에셋 탭의 두 숫자가 달라 문의 (유저: "6675자인데 비용 칸은 +1519 tok"). 버그가 아니라
// **단위와 기준이 둘 다 다른** 것이었다: 실황줄은 자 · 현재 상태(게이트 열림 반영),
// 비용 칸은 토큰 · lookup 없이(게이트 닫힘 = 항상 나가는 최소치). 얼헌 실측으로 확인 —
// 닫힘 5114자→1519 tok(비용 칸과 일치) / 현재 6675자→1974 tok(실황줄과 일치).
// - 실황줄에 자·토큰을 같이 적고 기준 차이를 한 줄로 밝힌다.
// - 팩 목록에 (조건 닫힘) 표시 — 실황줄이 지금 안 나가는 팩까지 세는 것처럼 보였다.
//
// ── v1.5.1 ────────────────────────────────────────────────
// 액션을 눌러도 "UI가 1초 만에 사라지고 반응 없는 것처럼" (유저 제보 — 막간 버튼 첫 실기).
// - 뿌리: display는 마커 번호가 앵커(lastOutIndex)와 다르면 '과거'로 보고 범례 없이 그리는데,
//   그 시점 스냅샷이 램 캐시에 아직 없으면 **현재 상태 + 범례**로 임시 렌더를 했다. 갓 연
//   채팅은 캐시가 비어 있어 과거 메시지마다 범례가 보이고, 배경 적재가 끝나는 순간(≈1초)
//   다음 재렌더에서 전부 증발한다. 토글 자체는 됐고 조작줄엔 무장이 떠 있었다 (그래서
//   "새로고침하면 눌린 걸로 나옴" — 캐시가 다시 비니까).
// - 캐시 미스 임시 렌더도 범례·하이라이트 없이. DOM 제자리 갱신(refreshStatusDom)도 같은 기준.
// - '과거' 판정을 idx !== lastIdx → **idx < lastIdx**로. 메시지 삭제·편집으로 앵커가 뒤처지면
//   마지막 메시지까지 과거로 몰려 범례가 아예 사라진다 (켤 자리가 없어짐).
// - 버튼 토글도 스냅샷에 저장 — /액션 명령 경로만 저장하고 버튼 경로는 램에만 있었다.
//
// ── v1.5.0 ────────────────────────────────────────────────
// 막간 — 주인공이 등장하지 않는 장면 (유저 제안: "페르소나가 존재하면 억지로 계속
// 등장시켜서" 조연들끼리의 장면·흑막 쪽 이야기를 굴릴 수가 없다. 프롬프트 토글에서
// 페르소나 칸을 빼거나 작가노트에 매번 적는 걸 버튼 하나로).
// - actions[].offstage: true — 그 액션이 발동한 턴(hold면 켜 둔 내내)에 두 가지가 걸린다:
//   ① 주인공 부재 지시문이 프롬프트 **맨 끝**에 (생성에 가장 가까운 자리)
//   ② 어댑터가 페르소나 원문을 프롬프트에서 걷어냄 (db에서 읽어 문자열 일치로 제거,
//      24자 미만이면 생략 — 남의 문장을 도려낼 위험. 실패해도 지시문은 그대로 간다)
// - 지시문의 핵심은 셋째 줄: 유저 입력의 신분을 "주인공의 말"에서 **연출 지시**로 바꾼다.
//   안 그러면 모델이 입력을 주인공 대사로 읽어 없앤 주인공이 되돌아온다.
// - promptState.offstageGuide로 문구 교체·끄기 (checkGuide·eventPriority와 같은 규약).
// - 얼헌: 🎬 막간 — 주인공 없이 (hold).
//
// ── v1.4.1 ────────────────────────────────────────────────
// 에셋 이름 확장자 관대화 (유저 제보: "[에셋에서 자동 감지]가 .webp까지 구분해서 이상하게
// 짤림"). 리수 버전마다 이름에 확장자가 붙기도 한다 (v0.83.1 독트린 — 대조는 양쪽에서
// 떼고 본다). 초상(party matchAssetName)만 지키던 규약을 에셋 팩 경로 전체로:
// - 자동 감지(detectSlotsFromNames): 알려진 이미지 확장자를 떼고 감지 — 어휘 오염
//   ("Smile.webp")과 '.' 구분자 오인 해소
// - 실존 대조: 런타임 getAssetNameSet + 편집기 커버리지 nameSet에 뗀 꼴도 합류 —
//   .webp 붙은 카드에서 대조가 전부 실패해 이미지가 조용히 생략되던 잠재 사고 봉인
// - 일반 꼬리 규칙 금지 그대로: 알려진 확장자 목록만 (.default 실사고, v0.83.2)
//
// ── v1.4.0 ────────────────────────────────────────────────
// 다중 상점 shops: [{ id, ...단수와 같은 필드 }] (최대 4, id 필수) — v1.3.0 화폐 확장의
// 남은 반쪽 ("무기점은 골드, 암시장은 달러" 세계). 같은 배포 봇 피드백의 후속.
// - 상점마다 지갑·재고·카테고리·밴드·when 독립. 우상단 버튼도 상점마다 하나 (tab=상점 id,
//   게이트 닫히면 그 버튼만 숨음) + 패널 안 상점 전환 칩 (열린 상점 2개 이상일 때).
// - 상태: 단수는 예전 그대로 state.shop(옛 세이브 무접촉), 배열은 state.shops[id].
//   단수→배열 전환 시 첫 상점이 state.shop 진열을 물려받는다 (편집기 [2호점 추가] 경로).
// - 첫 입고 피기백은 턴당 한 상점 (재고 빈 첫 상점부터 차례로 — 프롬프트 비대 방지).
//   다상점이면 응답에 "id" 에코를 요구, applyStock이 라우팅 (에코 누락 = 빈 상점 폴백).
// - 편집기 [상점] 탭: 다중이면 상점마다 필드 한 벌 + id 행 + [상점 추가]/삭제,
//   단수엔 [2호점 추가 (다중 상점으로 전환)]. 검증: id 필수·중복 거부·shop과 동시 사용 거부.
//
// ── v1.3.0 ────────────────────────────────────────────────
// 상점 화폐 확장 (배포 봇 피드백: "골드·실버·코퍼 세 종류 쓰니 환전이 하나만 지정돼서
// 물건을 10만 코퍼에 팔더라"). 요구의 정체가 둘이라 기계도 둘:
// - 표기 단위 사다리 units: [{label, ratio}] — 골드/실버/코퍼는 화폐 3개가 아니라 돈
//   하나의 표기다. 지갑·계산은 언제나 최소 단위(ratio 1) 정수 하나, 표기만 엔진이 쪼갬
//   (123456 → "12골드 34실버 56코퍼"). 지갑·진열가·시세판·거래 라인·통지 전부 적용,
//   입고 지시에도 "가격은 최소 단위 정수" 한 줄 동봉. 최대 4단, 검증이 ratio 1 강제.
// - 환전 다짝 exchange: [{...}] 배열 허용 (최대 4) — 원↔달러↔엔처럼 독립 지갑 여럿.
//   객체는 1개짜리로 정규화(하위호환 100%). 패널 환전 탭이 창구별 시세·사기/팔기,
//   편집기 상점 탭이 창구 행 추가/삭제. 검증은 창구별 + 지갑 중복 거부.
// 다중 상점(shops[])은 다음 단계.
//
// ── v1.2.5 ────────────────────────────────────────────────
// v1.2.4 진단줄이 에셋 탭 2열 그리드의 셀로 흘러들어 셀렉트가 짜부라짐 (유저 스샷).
// .sce-assets-live 전폭 행(grid-column 1/-1 + overflow-wrap)으로 고정.
//
// ── v1.2.4 ────────────────────────────────────────────────
// v1.2.3으로도 "메인인데 태그 안 나옴" 재현 (유저 제보) — 남은 용의자(저장 안 됨 /
// 재로드 팩 유실 / 주입문 0자 / 모델이 지침 무시)를 추측하지 않도록, 편집기 에셋 탭에
// **실행 중 스키마 기준 실황 진단줄** 추가: 삽입 주체·팩 목록(모듈/꺼짐 표시)·메인
// 주입문 크기·작업본과의 불일치 경고 (ai.getAssetInjection).
//
// ── v1.2.3 ────────────────────────────────────────────────
// 모듈 팩 봇에서 by:'main' 침묵 (유저 제보: "삽입 주체를 메인으로 해도 태그가 안 나옴").
// - 뿌리: 설치(저장) 직후 재로드의 자동 스캔이 ask=false — db 권한이 안 잡힌 환경이면
//   모듈 팩이 빈손이 되고, openPacks 0개면 메인 주입문이 통째로 생략된다.
//   [다시 읽기] 직후엔 되다가 저장하는 순간 사라지는 시차가 진짜 증상.
// - 설치 후 moduleManifests 봇이면 scanModulePacks(ask=true) 한 번 더 (버튼 경로라 팝업 OK).
// - 덤: sig() 비교가 모듈 팩을 세서 설치 되읽기 재시도(350ms×3)가 헛돌고 더티 판정도
//   안 맞던 것 수리 — origin:'module' 팩은 걷어내고 잰다.
//
// ── v1.2.2 ────────────────────────────────────────────────
// 편집기 에셋 탭이 모듈 팩(origin:'module')을 편집 가능한 척 보여줌 — 실제로는 스키마
// 저장이 걸러내고 [다시 읽기]가 매니페스트 원문으로 덮어써서, "실제 대조 해제가 자꾸
// 되살아나는" 실사고 (유저 제보). 모듈 팩 카드를 읽기 전용 + 원본 수정 안내로 교체
// (대조 끄기는 모듈 로어북의 ⚙simcore-pack JSON에 "verify": false).
//
// ── v1.2.1 ────────────────────────────────────────────────
// 현재 화제 기사가 첫 발행 전엔 흔적 없이 비어 있어 "패널에 따로 없는 건가"로 오인됨
// (유저 제보). 헌터넷 패널 최상단에 자리 표시(📰 아직 기사가 없어요 — 다음 턴 발행) 추가.
//
// ── v1.2.0 ────────────────────────────────────────────────
// 메신저 (유저 제안: "헌터 단말기답게 연락처 교환한 상대와 문자") — 게임 패널 5호.
// - core/messenger.js 신설: 1:1 최대 5방·단체방 최대 2방(NPC 4+유저=파티 5인 캡).
//   방은 **유저만 판다** — 연락처 풀은 contactsVar(얼헌: allies 동료 명부, "파티를 맺을
//   정도면 연락처는 안다"). AI는 방을 만들지도 없애지도 못한다.
// - 선톡: 매턴 확률(기본 0.25)+방별 쿨다운(기본 3턴), 시드 해시라 리롤 안정 — 뜬 턴만
//   보조 요청에 얹힘 (+300, 평턴 비용 0). when 게이트(게이트 안 통신 두절) 승계.
// - **핵심: 활성 방 하나만** 다음 인풋에 대화 원문(최근 10개)이 실린다 — 비활성 방은
//   순수 패널 전용 (서사가 모른다). 토큰은 유저가 고른 방만 쓴다.
// - 패널 발신 → 전용 보조 호출(채팅 턴 0): 인격 컨텍스트 = 캐릭터 **로어북에서 멤버
//   이름이 걸리는 문항 발췌**(persona, 인물당 700자) + notesVar("이름 — 변화") 델타 +
//   최근 서사. "누구세요" 답장 방지의 본체.
// - 말풍선 UI(안읽음 배지·활성 토글·Enter 전송), 나가기는 두 번 누르기(규칙 #6).
// - ⚠ 리롤하면 그 턴의 패널 대화도 되감김 (보드와 같은 스냅샷 규약 — 패널에 고지).
//
// ── v1.1.0 ────────────────────────────────────────────────
// 게시판 다양성 리워크 + 현재 화제 기사 (유저: "사용자 서사가 헌터넷에 계속 박제돼
// 다양성이 죽는다").
// - 뿌리: 종전 턴 갱신은 "이번 턴 서사에 반응할 일이 있으면"이라는 **반응형** 지시 —
//   글감이 구조적으로 주인공 서사뿐이었다.
// - board.postsPerTurn이 [min,max] 배열이면 **자율형**: 매턴 min~max개, 대부분 주인공
//   일행과 무관한 세계의 글 (주인공 관련은 공개 목격급 사건 때만 최대 1개). 숫자면 종전
//   반응형 그대로. NEW_PER_APPLY_MAX 4 → 6.
// - board.hot { every, label, guide }: N턴마다 갱신되는 "현재 화제" 기사 한 편 —
//   S랭커 동향·게이트 브레이크 활약담 같은 세계급 뉴스. 패널 최상단 고정(접기/펼치기),
//   메인엔 헤드라인 한 줄. 슬롯 교체식 (지난 기사는 안 쌓인다).
// - 출력 상한 가산식 재편: 바닥 400 + 첫 입고 2400 + 자율형 게시판 800 + 기사 400.
//   [새 소식] 버튼도 800 → 자율형이면 1600.
// - 얼헌: postsPerTurn [4,5], hot 5턴 주기 (maxPosts 20 유지 — 롤링 그대로).
//
// ── v1.0.9 ────────────────────────────────────────────────
// 상점 진열이 여전히 휑함 (유저: "갱신해도 카테고리별로 몇 개 안 나온다") — 총량 지시
// ("8~18개, 카테고리마다 골고루")를 모델이 카테고리당 1~2개로 뭉갬.
// - 엔진: shop 스키마에 perCat: [min, max] — 입고 지시가 "카테고리마다 4~6개씩 (빈 카테고리
//   금지)"로 바뀐다. CAPS.STOCK_MAX 30 → 48 (8카테고리 × 6).
// - 출력 상한 동반 상향: 첫 입고 피기백 1600 → 2800, 새로고침 1400 → 2400 (36개 JSON 분량).
// - 얼헌: perCat [4,6] + maxStock 36. 덤: shop.guide 중복 키 사고 수리 — guide가 두 번
//   선언돼 2축 짝 표기 지시("랭크급 희귀도", 레전드 입고당 1개)가 옛 가이드에 덮여
//   통째로 죽어 있었다. 한 키로 병합 ("레전드 절대 안 판다" 모순 문구는 제거).
//
// ── v1.0.8 ────────────────────────────────────────────────
// 상점 입고 잘림 (실사고: "얼터 스토어에 2~3개밖에 안 나온다") — v1.0.1 출력 클램프의 부작용.
// - 첫 입고는 턴 보조 호출에 피기백되는데 그 호출의 상한이 400(클램프 후 1000토큰) —
//   상태 갱신 + 게시판 + 재고 8~18개 JSON이 다 안 들어가 2~3개만 살아남고, stocked
//   플래그가 서서 자동 재입고도 안 돈다.
// - 첫 입고가 실린 턴만 1600(3200토큰)으로. 재고가 차면 auxSpec이 빈 문자열이라 평턴 400
//   그대로 — 비용 증가는 채팅당 첫 1턴뿐. 새로고침(물갈이)도 900 → 1400.
// - 이미 2~3개로 굳은 채팅은 재임포트 후 상점 패널 [새로고침]으로 물갈이하면 찬다.
//
// ── v1.0.7 ────────────────────────────────────────────────
// 긴급: v1.0.6으로도 번들 적용 실기 실패 (스샷 제보 2건 — "runInstall is not defined" +
// 가져오기는 되는데 적용 단계로 못 넘어감).
// - 뿌리 ①: installSchemaToCurrentChar·runInstall이 buildPanelSkeleton() **안**에 살았는데,
//   더티 배너는 스켈레톤 밖 renderPanel()이 그린다 → 배너 [지금 적용]의 runInstall 참조가
//   ReferenceError. 두 함수를 IIFE 레벨로 이사 (의존 식별자 전수 확인 — 전부 IIFE 레벨).
//   외부 참조 전수 스캔으로 같은 유형 부재 확인 (test-bundle 스코프 회귀 단언).
// - 뿌리 ②: 2단 확인 15초가 안내문 읽는 사이 만료 → 두 번째 클릭이 적용 대신 파일창을
//   다시 열어 "적용이 안 된다"로 보임. 60초로 늘리고, 만료 후 클릭엔 안내를 띄운다.
//
// ── v1.0.6 ────────────────────────────────────────────────
// 긴급: 번들 적용이 갓 임포트한 원본 카드에서 안 먹힘 (실사고 — "변수 하나도 없다고
// 캐릭터 저장이 안 됨", 유저가 세이브 가져오기 + [캐릭터에 적용]으로 우회해야 했다).
// - 뿌리 ①: setCharacter 직후 되읽기 레이스(v0.85.1과 같은 사연)를 번들 적용만 방어 안 함
//   → 옛 캐릭터를 되읽어 세션이 안 뜨고 "⚙simcore 없음"으로 오판. → 번들 속 스키마와
//   대조하는 재시도 3회(350ms) 추가, 보고 문구도 [인식됨 / 반영 지연 / 진짜 없음] 3분화.
// - 뿌리 ②: 편집기 작업본 미갱신 — 세이브 가져오기는 loadIntoEditor를 하는데 번들은 안 해서,
//   빈/옛 작업본이 더티 배너로 남아 [지금 적용]이 "변수가 하나도 정의되지 않음"으로 거부
//   (빈 작업본을 설치하려 든 것). → 적용·되돌리기 모두 편집기 동기화 (세이브와 같은 규약).
//
// ── v1.0.5 ────────────────────────────────────────────────
// 개조 번들 (배포 도구) — 남의 봇 개조판을 "카드 재배포 없이" 나누는 통로 (원본 카드
// 비허가 확인이 계기). 로어북 전체 + 정규식을 한 파일로 묶고, 받는 쪽은 원본 카드 위에
// 한 번에 교체 적용한다 — 수동 "전부 지우고 가져오기" 지옥(리수에 일괄삭제 없음)이 사라진다.
// - 스키마 항목(⚙simcore)도 로어북에 실려 함께 간다 → 배포물이 [플러그인 + 번들] 2개로 준다.
// - 교체 전 이전 로어북·정규식을 pluginStorage에 자동 백업 (캐릭터당 최근 3개) + [되돌리기].
// - 트리거스크립트(루아 브리지)·인사말·이미지는 안 건드린다 — 원본 카드의 것 유지.
// - 적용 확인은 패널 안 2단 버튼 (규칙 #6: 패널 위 host alert 금지). 형식: simcoreBundle: 1.
// - 순수 로직은 bundleFromChar/applyBundleToChar — 테스트 배수구 globalThis.__simcoreBundle.
//   테스트/test-bundle.js 신설.
//
// ── v1.0.4 ────────────────────────────────────────────────
// 긴급: 턴 없이 패널만 만진 변화가 리로드에 증발 (실사고 제보: "게시글 쓰고 갱신 누르니
// 내 글만 사라짐" — 옛 턴의 글은 스냅샷에 있어 살았고 유저 글만 램이었다).
// - 뿌리: loadForCurrentChar가 세션을 out:N에서 복원하면서 lastOutIndex는 -1로 둠 →
//   boardSaveNow·commitPanelChanges·수동 설정이 전부 `>= 0` 가드에 걸려 조용히 저장 생략
//   → 리로드(신안 재적용 [설치/업데이트]·플러그인 재부팅·채팅 전환 복귀)가 램만의 변화를 지움.
// - 수정: 로드 시 복원 앵커(out:lastCharIdx)를 lastOutIndex로 승계 — 패널 쓰기가 같은
//   자리에 저장돼 리로드를 살아남는다. 채팅 전환 시 이전 채팅의 낡은 앵커가 새 채팅에
//   새던 잠복 버그도 같이 잡힘. 되울림(v1.0.3)과는 무관 — 그 통로는 글을 지우지 않는다.
// - test-panelanchor.js 신설 (턴 없는 세션에서 /명령 저장 → 스냅샷 실측).
//
// ── v1.0.3 ────────────────────────────────────────────────
// 보드 되울림 (유저 제안: "유저가 키배를 뜸 → 다음 서사에 쓸 소스로 주고, 필요없으면 버려지는
// 1회용 통로") — board.echo (기본 켬).
// - 주인공이 패널에서 쓴 글·댓글이 **다음 전송에 1회** 스레드째(내 글 + 최신 반응 3개)
//   실렸다가 소거된다 — pendingNotifies 규약 (상점 거래 내역과 같은 길).
// - 반응 보조 호출의 성패와 무관하게 되울린다 (내 글 자체는 이미 사실). 반응 적용 뒤에
//   읽어서 키배·지원 댓글이 스레드째 실린다. mainLine의 "원문 금지"와 안 부딪힌다 —
//   주인공이 직접 한 일은 서사의 사실이라서다.
// - [편집기] [보드] 탭 체크박스 + SCHEMA_BOARD_RULES (규칙 #3). test-board.js 되울림 절.
//
// ── v1.0.2 ────────────────────────────────────────────────
// 상태창 위치 선택 (UI 개조 협업자 요청) — statusUI.position: 'bottom'(기본) | 'top'.
// - 저장 마커는 **항상 본문 끝 고정** (스트리밍 부분 반환·마커 유실 복구·beforeRequest 제거가
//   전부 "끝" 전제) — display 핸들러가 렌더할 때만 top이면 마커 자리를 비우고 본문 앞에 얹는다.
// - [편집기] [상태창] 탭에 '상태창 위치' 선택 (규칙 #3) + AI 규격서(position 행) + 탭 슬라이스
//   subOpt에 position (탭 내보내기/가져오기 왕복에 실림). 검증: top|bottom 외 값은 오류.
// - '중단'은 없다 — 본문 중간의 기준을 정의할 수 없다.
//
// ── v1.0.1 ────────────────────────────────────────────────
// 긴급: 스트리밍 중 보조 중복 호출 + 보조 출력 상한 미적용 (협업자 로그 제보, 리수 소스 확증).
// - [중복 호출] 리수는 스트리밍 중 **청크/플러시마다** editoutput 파이프라인을 다시 돈다
//   (index.svelte.ts 실측) → 우리 output 핸들러가 부분 텍스트마다 보조 호출 + 틱·이벤트까지
//   통째로 실행 (한 턴 10회+, 상태·시간 중복 갱신). 게다가 스트리밍은 빈 char 메시지를
//   미리 push한 뒤라 outIndex = message.length 계산이 +1로 밀려 있었다 (마커·스냅샷 오배치).
//   → 마지막 글이 이번 스트림의 부분 텍스트면(스트리밍 판정) 마커만 붙이고 아무것도 안 굴린다.
//   호출이 잠잠해진 뒤(1.2초 + 안정성 이중 확인) 저장된 실물 메시지로 **한 번만** 확정 처리.
//   이미지(aux/aux_flow)는 저장된 메시지에 소급 삽입. 다음 턴 beforeRequest가 미확정분을
//   먼저 정산(flush)하므로 순서는 깨지지 않는다. 비스트리밍은 기존 인라인 경로 그대로.
// - [출력 상한] runLLMModel엔 maxTokens가 아예 없다 (리수 v3.svelte.ts — mode/messages/
//   staticModel/allowPlugins만 통과). 보조가 메인과 같은 db.maxResponse(예: 10000) +
//   thinking 켜진 채 나가고 있었다. bodyIntercepter('replacer' 권한, 기보유)로 우리 보조
//   요청만 이중 걸쇠(호출 진행 중 + AUX_NUDGE 문장 실존)로 식별해 상한을 **낮추기만** 한다:
//   출력 = 요청분×2(최소 1000), Gemini thinking 예산 512, Claude thinking 1024.
// - 테스트 test-streamsettle.js 신설 (가짜 리수 스트리밍 시뮬 — 보조 1회·틱 1회·인덱스·클램프).
//   테스트·디버그 배수구 globalThis.__simcoreDrainTurn (대기 중 확정을 즉시 끝냄).
//
// ── v1.0.0 ────────────────────────────────────────────────
// 제작 도구 일괄 + 과거 상태창 — UI 개조 협업자 피드백 7건 전부 채택.
// - [#1 과거 상태창] 과거 마커를 그 시점(out:N) 스냅샷으로 렌더 — v0.11부터 주석 예고만
//   있던 것. display 핸들러가 동기라 램 캐시(histStates)로: out 저장 가로채기(store.save
//   랩) + 로드 시 배경 프리페치 + 캐시 미스는 현재 상태 폴백(keepN 밖 옛 메시지).
//   과거 렌더는 하이라이트·액션 범례·갈림길 없이 (현재 세션 조작 오독 방지).
//   테스트 test-histstatus.js (가짜 리수 부팅 실측 8케이스). [live-test] 재렌더 타이밍.
// - [#2 달력 미리보기] [달력] 탭에 시작 날짜 기준 실물 카드 — 기념일·일정·기한 점 +
//   사용자 CSS(scopeCss '.sce-cal-preview' 격리). monthView(코어)와 같은 데이터.
// - [#3 프리셋 미리보기] [새 시작] 탭 프리셋마다 [👁] — 기본→적용값 diff + startAt +
//   그 상태의 상태창 렌더.
// - [#4 1턴 시험 실행] [규칙·이벤트]·[액션] 탭에 🧪 — 실제 엔진을 헤드리스로 한 턴 굴려
//   changeLog 출처(액션/판정/시간/틱/이벤트/랜덤)별 타임라인 + 통지 + 최종 diff.
//   시드 고정·[🎲 다른 운으로]. 보조 AI 없는 시스템 축 전용.
// - [#5 계산 미리보기] 파생 카드에 "시작값 기준 계산: N" 한 줄 + 랜덤 이벤트마다
//   시작 상태 실효 확률(발동% × weight/Σ후보, 조건 불충족 표시, 쿨다운 제외 근사).
// - [#6 참조 펼쳐보기] 변수·파생 카드의 참조 경고가 "N곳에서 참조 중" 펼치기로 —
//   파생/틱/이벤트/지시문/액션/판정/계약표/상태요약/상태창/프리셋/편성표/달력/보드/상점/
//   시나리오 역색인(varReferenceIndex). 분류 밖은 '기타'로 과소보고 방지.
// - [#7 시간 탭 왕복] TAB_SLICES.time — [시간] 탭에 요청서 내보내기/JSON 가져오기.
//   요청서에 달력 전환 위험 경고 동봉. 일반 패치의 time 금지는 유지.
//
// ── v0.99.0 ───────────────────────────────────────────────
// 하루 경계 넘김 — UI 개조 협업자 제안 채택: 🌙 하루 마무리가 "다음날 아침"을 박지 않는다.
// 시계 선반영을 버리고 장면이 먼저, 시계가 따라온다 (explicit 진행의 원래 결).
// - [템플릿 romance·daily] 🌙 = day_break 깃발 + "시각은 문맥이 정한다" inject/지시문(리롤
//   생존) → 보조가 장면의 시간대만 wake_at(enum 새벽~심야)로 보고 → day_break_sync 이벤트가
//   시간대→대표 시각 삼항 사슬(H)로 "다음으로 돌아오는 그 시간대"까지의 분
//   (((H*60-now)+1439) % 1440 + 1)을 굳히고 깃발을 내린다. 무조건 +1일이 아니다 —
//   밤 취침+새벽 = 익일 05:00, 새벽 취침+아침 = 같은 날 08:00 (29시간 수면 방지 —
//   옛 "다음 08:00" 공식의 미덕 유지). 깃발 해제는 이벤트가 (자가 회복 래치).
// - ⚠ 시각을 int로 받으면 안 된다 — 보조 changes의 숫자는 델타 적용 (실측: -1에 5를 적으면
//   4가 된다). enum은 절대값 적용. daily rules의 중복 events:[] 키 제거 (덮어쓰기 버그).
// - [규격서] time 절 "하루 경계 넘김" 패턴 + 델타 함정 경고. [편집기] SCHEMA_TIME_RULES.
// - 엔진 무변경 — 전부 스키마 표현. 이벤트가 굳힌 진행은 다음 전송 반영 (아이돌 night_auto와
//   같은 규약). 시각 enum 봇(얼헌형)은 이 패턴 불필요 — 날짜·시각 분리가 이미 정답.
//
// ── v0.98.0 ───────────────────────────────────────────────
// 보드 카테고리 + 템플릿 목록 필터 (얼헌 파티 모집판·게이트 지도 — 유저 요청 2건.
// 새 기계는 안 만들었다: 모집판은 보드 탭, 지도는 편성표 대장 템플릿(v0.89)이 받는다).
// - [코어 board] categories(1~6) — 패널이 탭(전체+칸별)으로 나뉘고 글마다 cat이 붙는다.
//   어휘 밖 칸은 첫 칸 보정 (상점 cat 규약). digest·auxSpec·인터랙션 프롬프트에 어휘 전파.
// - [코어 engine] renderTemplate `{목록:tags:필터}` — 그 문자열을 품은 항목만 칩으로.
//   지도 대장이 한 목록(gates)을 구역 칸에 나눠 꽂는 통로.
// - [어댑터] 보드 목록 카테고리 탭 + 글쓰기 칸 선택(보던 탭이 기본) + [칸] 표시.
//   패널 열 때 shopView.exchQty 미초기화로 환전 입력칸에 "undefined" 찍히던 것 수정.
// - [편집기] [보드] 탭 카테고리 칸 + SCHEMA_BOARD_RULES. [검증] categories 1~6 문자열.
// - [얼헌 P6] 파티 편성(allies 명부 + party1~4 슬롯 — 영입은 이야기가, 편성은 버튼이,
//   동행 지시문 {partyN} 치환) + 헌터넷 모집 칸(명단 지원 댓글 지침) + 게이트 지도 탭
//   (서울 5권역 그리드, {gates:tags:권역}, fab 🗺️). 테스트 72→84.
//
// ── v0.97.0 ───────────────────────────────────────────────
// 상점 환전 창구 (얼헌 코인↔원화 — 원작 캐논: 공식 거래 금지, 블랙 마켓만 ₩1,000/코인).
// - [코어 shop] exchange: { var, rate, spread?, label? } — 통화 1 = rate(상대 지갑).
//   살 때 rate×(1+spread), 팔 때 rate×(1-spread). 계산·정산 전부 엔진, 보조 호출 0.
//   통지 접두는 exchange.label — 상점 본체와 다른 장소일 수 있다 (얼헌 "암거래 환전").
// - [어댑터] 상점 패널 [💱 환전] 탭 — 상대 지갑 잔액·시세 표시·수량 입력·사기/팔기.
// - [편집기] [상점] 탭에 환전 4칸 (상대 지갑/환율/수수료/창구 이름) + 규칙 한 줄.
// - [검증] exchange — 상대 지갑 실존·숫자·통화와 다름, rate 양수, spread 0~0.9.
// - [얼헌] shop.exchange 배선 + alter_store 지시문에 환전 캐논 + 변환기 lore=1
//   (알터 스토어·코인·블랙 마켓 세계관 복원 — 스토어 항목은 키워드 활성으로 강등,
//   블랙 마켓 가격표는 economy=0으로 계속 배제: 심코어판 코인 경제와 스케일 충돌).
//
// ── v0.96.0 ───────────────────────────────────────────────
// 상점 (얼터헌터 "알터 스토어" 흡수 — 유저 지목 고질병: 로어북 상점의 "S랭크 스킬북 뇌절"과
// 가격 계산). 카테고리 탭·구매·판매(감정)·매입 시세판. docs/design-얼헌-개조.md §P4.5.
// - [코어 shop] state.shop { stock, buying, log } — 스냅샷에 실려 리롤과 되감김.
//   뇌절은 구조로 잡는다: 등급 어휘(grades)·가격 밴드(bands)를 스키마가 정하고 밴드 밖
//   진열은 sanitize가 거부/클램프. 결제·잔액·수량·수량 병합("포션 2")은 엔진이 결정적으로.
// - 거래 내역의 수명 (유저 설계 그대로): pendingNotifies로 **다음 전송에 한 번 실리고 자동
//   소거** + lastChanges 원장(보조 이중 계산 방지) + 패널 로그 6건 회전. 영구 누적 없음.
// - 첫 입고는 턴 피기백(재고 빈 동안만 — 이후 매턴 비용 0), 물갈이는 패널 [새로고침],
//   감정(시세판 밖 판매)만 전용 보조 호출. 구매·시세판 판매는 보조 호출 0.
// - [어댑터] 게임 패널 4호 — 지갑·카테고리 탭·매입 창구. when 거짓이면 버튼째 숨김.
// - [편집기] [상점] 탭 (지갑/목록/카테고리/등급/밴드/매입률/지침) + SCHEMA_SHOP_RULES.
// - [검증] shop 섹션 — currency/buyTo 실존·타입, 밴드 정합, "밴드 없으면 뇌절 재현" 경고.
//   테스트 테스트/test-shop.js.
//
// ── v0.95.0 ───────────────────────────────────────────────
// 커뮤니티 보드 (얼터헌터 "헌터넷" 흡수가 발단 — docs/design-얼헌-개조.md §P4).
// 원본(LightBoard류)은 게시판 원문을 메인 모델이 본문과 함께 출력해 매턴 재전송하는
// 구조였다 — 여기선 상태(스냅샷)에 실어 재전송 비용을 없앤다. 자체 구현 (코드·포맷 무관).
// - [코어 board] state.board { seq, posts } — 스냅샷에 실려 리롤과 함께 되감긴다.
//   턴 갱신은 기존 보조 호출에 얹힘 ("board" 필드, 추가 호출 0). 조회수·추천은 시스템이
//   굴린다 (시드 rng). 메인에는 화제 한 줄만 (mainInject). when 게이트(통신 두절 등).
// - [어댑터] 게임 패널 3호 '보드' — 우상단 버튼, 목록/읽기/쓰기 3면. 글쓰기·댓글·새 소식은
//   **채팅 턴 없이** 전용 보조 호출로 보드만 갱신 (turnBusy 경합 차단, out 스냅샷 정합).
// - [편집기] [보드] 탭 — label/icon/topics/guide/postsPerTurn/maxPosts/when/mainInject/css
//   + AI 도구(생성·내보내기, SCHEMA_BOARD_RULES). 규칙 #3 (엔진 기능엔 편집기 칸).
// - [검증] board 섹션 — 타입·범위·when 표현식·"topics도 guide도 없음" 경고.
//   테스트 테스트/test-board.js.
//
// ── v0.94.1 ───────────────────────────────────────────────
// 실기 제보: 내장 AI 생성이 "형식 검사 불합격"만 반복 → 유저가 재생성만 돌리다 포기.
// 원인 갈래 분리 — 응답 길이 한계로 **잘린** JSON은 재시도해도 같은 자리에서 잘린다
// (생성 기본값이 보조 모델이라 출력 상한 짧은 환경에서 통짜 생성이 구조적으로 걸림).
// - [편집기] looksTruncatedJson: 괄호 안 닫힘/문자열 중단 = 잘림 판정 (1.5KB 이상만).
//   잘림이면 2차 자동 재시도 생략(무익) + 전용 안내: ① 생성 모델을 메인/직접 지정으로
//   ② 리수 설정에서 응답 최대 길이 늘리기 ③ 기능 카드·탭 요청으로 쪼개기.
// - [편집기] 탭 붙여넣기·원본 직접 편집 게이트에도 같은 잘림 안내 (외부 AI에서 복사해 온
//   잘린 응답). 형식 오류 안내에 "외 N건" 표기.
//
// ── v0.94.0 ───────────────────────────────────────────────
// 배포 구멍(유저 제보): 이미지는 모듈에 실을 수 있는데(module_assets) 팩 정의 — 에셋 지침
// (format·슬롯·usage·when) — 는 스키마 전용이라 에셋 애드온을 모듈로 배포할 방법이 없었다.
// - [코어 assets] 모듈 로어북 규약 ⚙simcore-pack: 항목 내용 = 팩 JSON. parseManifest +
//   mergeModulePacks — 후보를 스키마에 얹어 검증 통과분만 origin:module로 병합 (깨진
//   매니페스트가 봇을 못 죽인다). id 충돌은 스키마·선착 우선, source 비면 모듈 이름, 상한 8.
// - [어댑터] assets.moduleManifests 옵트인 봇만 로드 시 활성 모듈 스캔·병합 (기본 봇 무비용).
//   매니페스트 모듈의 이미지 이름은 module_assets 꺼져 있어도 실존 대조에 합류.
// - [편집기] 에셋 탭 📦 모듈 팩 매니페스트: 옵트인 체크 + [다시 읽기](권한 팝업 경로) +
//   배포자용 팩 → 매니페스트 JSON 내보내기. 병합 팩은 편집기·저장에서 걸러진다 (유령 방지).
// - [검증] assets.moduleManifests 불리언. 테스트 test-modpacks.js 18케이스.
//// ── v0.93.1 ───────────────────────────────────────────────
// 해금 변수의 기록 기준 — 실기 피드백: "AI가 해금 변수를 언제 움직일지 어디에 적지?"
// 답은 원래 있던 자리(변수 desc — 보조 계약표에 그대로 실린다)인데, 시나리오 탭도
// 요청서도 그 연결을 안 가르쳐 줬다. 원칙: AI에게 "해금 판단"을 맡기면 자율주행 실패
// 재현 — AI는 일어난 일만 기록(desc = 기록 기준), 판단은 해금식+minTurns가 한다.
// - [검증 warn] 해금이 읽는 변수가 updater.allow에 있는데 desc가 비면 경고
//   ("보조 AI는 desc를 보고 언제 움직일지 정합니다"). allow 밖(이벤트·판정이 세우는
//   변수)은 대상 아님 + 해금식 문자열 리터럴 오인 방지 — 오탐 0 원칙.
// - [시나리오 탭 힌트] "desc가 곧 페이스 손잡이" 안내 한 절.
//
// ── v0.93.0 ───────────────────────────────────────────────
// 시나리오레이터 4차 — 유저 눈에 보이는 자리. 모델 주입(1차)·편집(2차)·진단(3차)에 이어
// 마지막 조각: 플레이어가 이야기의 어디에 서 있는지를 스포일러 없이 보여 준다.
// - [{scenario} 진행 칩] 현재 막 라벨 + (i/N막)만 — direct·secret은 상태창에도 절대 안
//   실린다 (은닉 보장 §3-1은 유저 눈에서도). 자동 구성이면 상태창 맨 위 자동, 템플릿
//   모드면 {scenario} 자리(예약 자리 — RESERVED_SLOTS 합류), 대장(패널) 탭도 동일.
// - [📖 막 전환 하이라이트 카드] §6 미결 3의 답 — notify는 AI쪽 통지라 유저 눈에 안
//   보였다. 전환 순간을 엔진이 원장(changeLog)에 남기고(id=시나리오 라벨, 잠복 → 전개),
//   하이라이트 카드·변화 로그·보조 AI 원장(lastChanges)이 전부 그 한 줄에서 그려진다.
//   onEnter 효과도 카드 창구(📊·🎒)에 합류.
// - [AI 창구 계약] 배치 규격서에 {scenario}·{scn_label}(시나리오 켜진 봇만 — 빈칸 유도
//   방지), 스킨 규격서에 .sim-scn, 대장 템플릿 안내에 {scenario}.
// - [템플릿 실물 예시] rpg '무너진 봉인' 3막 — unlock 정석 패턴(`level >= 3 or
//   scn_turns >= 8`: 성장이 빠르면 먼저, 아니어도 N턴이면 이야기가 움직인다) + minTurns +
//   onEnter(인장 습득) + 막별 secret. 전 템플릿 진단 스윕이 이 예시의 품질 게이트를 겸한다.
// - 남은 것: 실기(막 전환 체감 페이스, 칩·카드 실화면) + 새 시작 페이지 막 강제 이동(§4).
//
// ── v0.92.0 ───────────────────────────────────────────────
// 시나리오레이터 3차 — 진단. "카드로 만든 시나리오가 진단에 걸리면 요청서 버그"의 품질
// 게이트가 시나리오에도 닫힌다 (design-기능프리셋.md §병행 트랙).
// - [닫힌 막 = high] 죽은 이벤트와 같은 기계 — 해금이 읽는 값의 병목을 짚는다
//   ("finds >= 2 인데 관측 최고 0"). 은닉 설계라 결함의 값이 더 크다: 이 막부터의
//   이야기·secret은 플레이어가 영영 못 본다. 막은 선형 사슬이라 **첫 닫힌 막 하나만**
//   신고하고 뒤는 "함께 잠김 — 원인은 이쪽 하나"로 붙인다.
// - [변명 사다리 재사용] 설정 게이트(byPlayer/byAI) → 긴 판 재확인(onlyLonger —
//   'scenario:막id'가 fired 창구로 이미 흐른다) → AI 담당 문턱(aiGated, "문턱을 내리지
//   마세요"). 오탐 0 원칙 그대로 (전 템플릿 확인 테스트 포함).
// - [이야기 페이스 = mid] 마지막 막까지 평균 ≤ max(5, 판의 25%)턴이면 기승전결이 초반에
//   소진된 것 — 루아 자율주행의 "세 턴 만에 종결" 재현. minTurns를 주면 지적이 사라진다
//   (페이스 손잡이가 작동한다는 것까지 테스트가 확인).
// - [오탐 방어] writerMap에 onEnter 합류(전환 효과만 받는 변수의 "고정 변수" 오탐 차단),
//   trackIds에 scn_turns(그걸 읽는 조건의 병목 지목용).
// - 남은 것: 상태창 {scenario} 자리 + 템플릿 실물 예시 + 실기(막 전환 체감 페이스).
//
// ── v0.91.0 ───────────────────────────────────────────────
// 시나리오레이터 2차 — 편집기 [시나리오] 탭 + AI 경로.
// - [탭] 3막 골격 버튼 → 막 카드 (id·라벨·국면 select / 해금 조건·최소 체류 / 연출 지시 /
//   🔒 내막 — "이 막이 열리는 순간부터 공개"를 UI가 계속 상기 / 전환 통지·효과 = effectRows 공유).
//   막 0개면 scenario 키 자체를 걷는다 ("없음 = 꺼짐").
// - [AI 슬라이스] TAB_SLICES.scenario (통째 교체 — 막은 선형 사슬이라 부분 교체가 오히려
//   어긋난다) + 적용 전 계획(사라지는 막 신원) + SCHEMA_SCENARIO_RULES: v1.3 생성 규칙 이식
//   (표면 상황만 / 내막·반전은 secret 칸 / 주인공의 행동·결말 금지) + 쓰는 순서 4단.
// - [🧩 카드] 📖 시나리오 — "설정에 어울리는 중심 사건 하나를 3~5막으로". 전제 = 변수 1개
//   (해금이 읽을 흔적이 있어야 한다). [통짜 규격서] scenario 절 + 최상위 키 등재 —
//   내장 AI 생성이 "봇 설명 읽고 5막 제안"을 공짜로 얻는다 (설계 §3-3).
// - PATH_TABS $.scenario → aiReady (검증 오류를 [내보내기]로 고칠 수 있는 탭).
// - 다음: 진단(도달 불가 막 — 죽은 이벤트와 같은 기계) + 상태창 {scenario} 자리 + 템플릿 실물.
//
// ── v0.90.0 ───────────────────────────────────────────────
// 시나리오레이터 1차 — 엔진 수직 슬라이스 (core/scenario.js, 설계 docs/design-시나리오레이터.md).
// 배포자가 시나리오 라인(acts)을 등록하면 조건을 만족할 때마다 다음 막이 해금된다 —
// 이야기 속도·흐름 제어. 루아 자율주행(기승전결 통짜 주입 → 세 턴 만에 종결)과
// 중심 사건 생성기 v1.3(⏫ 국면진행이 유저 버튼)의 실패를 조건식+minTurns가 대체한다.
// - [은닉 = 구조] 모델은 전체 시나리오를 영영 못 본다. sendPhase 3.5.5가 현재 막의
//   direct + 이미 열린 막들의 secret만 싣는다. secret 0개면 절 자체가 없다("내막이
//   있다"는 신호도 스포일러). "미공개 = 거짓이 아니라 아직" 어법은 S2D에서 이식(설계 §5).
// - [전환 = outputPhase 8.5] 이벤트(⑦·⑧) 뒤라 이번 턴 이벤트가 세운 변수를 해금이 바로
//   읽는다. 턴당 한 막. minTurns = 페이스 바닥(조건이 먼저 차도 직전 막에서 N턴).
//   unlock은 rand() 금지 — 전환은 결정적이어야 진단·리롤·세이브가 안 어긋난다.
//   onEnter 효과 + notify(다음 전송 합류) + firedEvents 'scenario:막id' 창구.
// - [상태 = vars 예약 키] scn_idx·scn_turns (time_epoch 계열 — 스키마 vars 아님,
//   allow에 못 올림 = 보조가 못 만짐). 조건식·상태창 노출은 scn_act(막 id)·scn_label(라벨)·
//   scn_turns — 진행 표시는 라벨만, 스포일러 없이.
// - [검증] 중간 막 unlock 없음=오류(영영 안 열림), 예약 이름 충돌, intensity 오타,
//   onEnter 효과 검사, 첫 막 unlock/minTurns=경고(무시됨). intensity 5종(잠복·전개·
//   고조·절정·해소) 기본 문구는 v1.3 [연출 지시] 출발 + S2D FACT LOCK 양면 어법.
// - 다음: 편집기 [시나리오] 탭 + tabAiTools 슬라이스 + 내장 AI 생성 + 진단(죽은 막) + 실물 예시.
//
// ── v0.89.2 ───────────────────────────────────────────────
// 실사고: 모듈 Lua 트리거(챕터요약)가 onOutput에서 setChat으로 메시지를 다시 쓰는 사이
// ⟦simcore:N⟧ 마커가 사라져 그 메시지의 상태창이 실종 (마커는 output 반환값으로 붙는데,
// 뒤에 도는 스크립트가 낡은 사본으로 덮으면 조용히 증발 — 어떤 서드파티 스크립트든 가능).
// - [어댑터] 마커 유실 자가 복구: 저장 4초·12초 뒤 점검, 마커가 통째로 없으면 재부착.
//   리롤 중(char 메시지 없음/turnBusy)·이미 마커 있음이면 불개입.
// - [어댑터] output 처리 실패(catch)에도 마커는 붙인다 — 상태는 못 굴려도 상태창은 산다.
// - 스키마 무변 — 플러그인 재임포트만.
//
// ── v0.89.1 ───────────────────────────────────────────────
// 베리디아 난이도 프리셋 재설계(희망적/보통/리얼리티)에서 드러난 갭: 프리셋은 변수 초기값만
// 바꾸는데 randomEvents.chancePerTurn이 숫자 상수라 "프리셋마다 사건 빈도"가 불가능했다.
// - [코어] chancePerTurn에 식 허용 (0~1 스케일, 매 추첨마다 현 상태로 평가) — 난이도 변수
//   (hardship 등)를 읽게 짜면 프리셋 하나로 빈도가 따라 움직인다. 깨진 식은 0으로 강하.
// - [편집기] 확률 칸이 숫자(%)와 식을 다 받음, 카탈로그 표기 '식(...)', 패치 takeChance 완화.
// - [검증] 식이면 checkExpr (rand 금지). 숫자 봇 무변 — 플러그인 재임포트만.
//
// ── v0.89.0 ───────────────────────────────────────────────
// 베리디아 리메이크 P1 (docs/design-베리디아-리메이크.md): 상태창에 우겨넣은 참고 정보(인물
// 대장·영지 대장)를 "열었을 때만 그리는" 패널로 옮길 자리가 없었다 — 패널 탭은 slots/actions/
// items 3종뿐. + 유저 채택: 다른 봇의 "플로팅 버튼 → 종이 카드 팝업" UI.
// - [코어] party.tabs[].template (대장 탭): 상태창과 같은 자리표시자 HTML을 탭 본문으로.
//   render.renderPanelTemplate — {uid}='scg' 고정, {choices}는 빈칸(패널에선 좌표 히트테스트가
//   안 닿아 안 눌린다), 임베드 <style>은 #sc-game로 스코핑. 슬롯 없이 template만 있는 탭 허용.
// - [코어] party.tabs[].fab: 아이콘을 적으면 우상단 유틸 버튼 줄에 그 탭 전용 버튼이 생기고
//   누르면 openGamePanel('party', tabId)로 바로 열린다 (📋 인물 대장, 🗺️ 탐사 지도 식).
//   when으로 숨은 탭의 버튼은 유지 — 눌리면 첫 탭 폴백 + 안내 (버튼 줄 출렁임 방지).
// - [편집기] 탭마다 '플로팅 버튼' 칸 + '대장 템플릿' 접이 칸 (축약형에도, 규칙 #3).
//   party AI 규격에 template/fab 예시, 패치 다이제스트에 템플릿 탭 참조 경고.
// - [검증] template 자리표시자 검사(상태창과 같은 checkTemplateRefs), fab 글리프 길이,
//   tabs와 최상위 template 혼용 금지. 스키마 형식 추가 — 기존 봇 무변, 플러그인 재임포트만.
//
// ── v0.88.0 ───────────────────────────────────────────────
// 실기 지적: 구조 라우팅(v0.87.3)으로 한 인물이 field set을 여럿 받게 됐는데, "어느 세트를
// 언제 쓰나"의 판단 기준이 없다 — 에셋 명 조합만 받으면 보조가 헷갈린다.
// → 팩에 usage(쓰임새 한 줄) 필드 추가:
// - [코어] auxImageSpec: 각 field set 줄에 "use for: <쓰임새>"로 실린다 (변형 합치면 ' / ' 연결).
//   uniform(팩 하나) 경로에도 한 줄, mainInjectionText의 팩 줄에도 얹음.
// - [편집기] 팩 설정에 '쓰임새 (AI 선택 기준)' 칸 (규칙 #3) + 임포터 규격에 usage 추가.
// - [검증] usage 문자열 검사(200자 경고) + 구조 공존인데 어느 한쪽이라도 쓰임새가 없으면
//   경고 — 공존 자체가 성립해도 기준 없인 보조가 아무 세트나 고른다.
//   스키마 필드 추가지만 기존 봇 무변 (usage 없으면 예전 지시 그대로). 플러그인 재임포트만.
//
// ── v0.87.3 ───────────────────────────────────────────────
// 실사고: 감정 팩(who·wear·emo)과 성행위 팩(who·wear·act)이 인물을 공유하자 뒷팩이 통째로
// 죽었다 ("사용처가 다른데 겹친다는 이유로 못 쓰게 만든다"). 라우팅이 인물→팩 하나였던 탓.
// → 구조 라우팅: 어느 팩이냐는 보조가 **채운 칸**이 고른다.
// - [코어] resolveImage: 후보 팩 전부(routePacks, 선언 순)를 1차 정조합 → 2차 폴백 사다리
//   순으로. 정조합이 먼저라 앞 팩의 폴백(emo→default)이 뒷팩용 선택을 삼키지 않는다.
// - [코어] auxImageSpec: 칸 id가 부분집합인 팩은 기존처럼 어휘만 넓히고(성인 게이트 패턴),
//   새 칸을 가진 팩은 "field set (1)/(2)"로 나란히 전송 — 보조는 한 세트를 통째로 채운다.
//   팩 id는 여전히 지시에 안 나온다.
// - [검증] 겹침 경고는 필수 칸 구성이 겹칠 때만 — 구조가 다른 공존은 정상 설계.
//   렌더러·스키마 무변 — 플러그인 재임포트만 하면 된다.
//
// ── v0.87.2 ───────────────────────────────────────────────
// 실사고 둘 (아이돌 실기):
// ① 백화점 업무 D-1에서 🌙 누르고 자고 일어나니 이미 펑크 — 🌙이 정산한 턴의 출력에서
//   보조 AI가 방금 그려진 밤 장면을 보고 night_req를 또 켜면, 같은 턴 이벤트(night_auto)가
//   둘째 밤을 정산했다 (하루가 이틀로 → 일하는 날 아침 전에 job_days 0 펑크 분기).
//   유령 밤 빗장 night_done(정산 직후 2, onTurn이 1씩 감쇠) + night_ghost_clear 이벤트로
//   메아리 깃발을 지운다. 진짜 새 밤은 한 턴 뒤(빗장 0) 정상 정산.
// ② "거리 홍보 및 게릴라 버스킹 @-22" 유령 일정 — itemExpiry가 음수 기한을 못 읽어
//   null(무기한)이 됐다. @-N도 기한으로 읽어 만료 정리에서 즉시 빠지게 (itemValue의
//   기한 떼기도 같이 — 안 떼면 -22가 항목 값으로 잡힌다).
//   스키마 변경(night_done) — 플러그인 재임포트 + 아이돌 JSON 재적용 필요.
//
// ── v0.87.1 ───────────────────────────────────────────────
// 실사고(세 번째 제보): 상태창 액션 버튼이 또 안 눌린다. 이번엔 클래스가 아니라 **속도**였다:
// ① 좌표 히트테스트가 후보마다 at(i)·getBoundingClientRect를 차례로 await — RPC 한 왕복씩
//   n번. 액션 83개(아이돌 v0.87.0) × 메시지마다 그려지는 상태창 = 후보 수백 개, 클릭 한 번에
//   몇 초 → "안 눌린다"로 체감. 전 후보 병렬 조회로 왕복을 겹치고(전체가 한 왕복 수준),
//   스캔 중 중복 클릭은 버린다 (hitScanBusy).
// ② 즉시 갱신이 라디오를 새로 써서 보던 탭이 첫 탭으로 튕겼다 — 13탭이 되면서 누른 칩이
//   눈앞에서 사라지는 수준. 갱신 전에 input:checked를 읽어 그 탭에 checked를 되단다.
// ③ 되읽기 검증(slice 60 비교)이 항상 실패 — setInnerHTML의 기본 DOMPurify가 마크업을
//   정규화한다 (실측: <details open> → open=""). 렌더마다 숨은 나온스 스팬으로 교체.
//   ①~③ 전부 어댑터만 — 스키마 변경 없음, 플러그인 재임포트만 하면 된다.
//
// ── v0.87.0 ───────────────────────────────────────────────
// IDOL 상점 대확장 (실기 요청, 전부 *_DEFS 표 생성):
// ① 굿즈 8종 — 포토카드/캔뱃지/아크릴/응원봉/족자봉/ASMR/화보집/다키마쿠라.
//   물판·팬서비스 판매 보정은 6종분 캡 (min(count,6)).
// ② 콜라보 5종 — 빵/편의점/프랜차이즈/전자제품/자동차. 브랜드가 계약금을 낸다 —
//   문턱은 rank_n, 체결 즉시 계약금+인지도+팬 (collabs 목록).
// ③ 음지 굿즈 8종 — 타락도 사다리(10~60)로 열림, 만들 때마다 타락+멘탈− (sgoods).
// ④ 시크릿 팬서비스 5종 — 악수회/사진회/라이브/팬미팅/스트립쇼. 돈을 받는 팬서비스:
//   설득 판정(SHADY_TIERS 5단 추가) + 음지 굿즈 현장 판매. 값은 멘탈·유대·타락,
//   스트립쇼는 이름값까지. 탭 4개 신설(굿즈/콜라보/음지 굿즈/음지 팬서비스 — 뒤 둘은 타락 게이트).
//
// ── v0.86.5 ───────────────────────────────────────────────
// 실사고: 범례 클릭·패널 조작 후 상태창이 통짜 텍스트로 깨졌다. 원인 — 리수 파이프라인은
// 메시지의 class 전부와 <style> 선택자에 x-risu- 접두를 붙이는데, 즉시 갱신(v0.85.4)이
// 접두 없는 원본 클래스로 갈아 끼워 접두된 CSS와 어긋났다. v0.86.2가 범례 클릭마다
// 즉시 갱신을 물리면서 "누르면 깨진다"로 드러났다. 갈아 끼우는 HTML의 클래스를
// 파이프라인 규칙 그대로(x-risu-·hljs 시작이면 유지) 미리 접두 — 멱등이라 재갱신도 안전.
// 히트테스트([class*=\"sim-hit\"])와 decodeHitClass는 접두를 이미 다룬다.
// [live-test] 범례 클릭 → ✅ 표시 + 상태창 모양 유지 확인.
//
// ── v0.86.4 ───────────────────────────────────────────────
// 하이라이트 카드 — 실기 제보: 판정 성패·돈·소지품·스탯처럼 체감 나는 변화가 전부
// 접힌 로그 속에 있어 채팅에서 안 보였다. 이번 턴 변화 중 골라(판정 무조건, 숫자는
// 합산 델타, 목록은 넣고 뺀 것, enum은 A→B, bool 제외 — 깃발 소음) 상태창 맨 위
// 접힘 바깥에 게임 알림풍 카드로 세운다. 성패가 카드 색을 정한다.
// statusUI.highlights: 'off'로 끔 (편집기 상태창 탭에 칸 추가 — 규칙 #3).
//
// ── v0.86.3 ───────────────────────────────────────────────
// 실사고: 무대 당일 일감이 그냥 사라지고 돈이 안 들어왔다. 원인은 이벤트 순서 —
// 서사가 "무대를 치르고 잠들었다"면 보조가 stage_req·night_req를 같이 켜는데,
// night_auto가 배열에서 먼저라 밤 정산이 먼저 굴러 펑크(일감 소멸·보수 0)를 박고
// stage_auto는 조건(job != '없음')이 죽었다. stage_auto/live_auto를 night_auto
// 앞으로 재배치 — 무대가 먼저 정산되면 밤의 펑크 분기는 그 무대를 노쇼로 안 몬다.
// 보조 guide에도 명시: 무대 친 날 밤을 넘겼으면 두 깃발을 같이 켜라.
//
// ── v0.86.2 ───────────────────────────────────────────────
// ① 범례 클릭이 무장은 시키는데 ✅ 표시가 다음 메시지까지 안 보였다 (실기 제보 —
//   v0.85.4의 제자리 갱신이 패널 경로에만 물려 있었다). onActionButton 성공 토글에도
//   refreshStatusDom을 연결. [live-test] 범례 클릭 → 즉시 ✅ 확인.
// ② 잠긴 액션 접기 — 액션 60개가 되자 잠금 사유가 벽지가 됐다 (모바일 지옥).
//   누를 수 있는 것만 펼치고 잠긴 것은 "🔒 잠긴 액션 N개" 접힌 상자로 —
//   해금 조건(다음 목표)은 상자 안에 그대로 남는다.
//
// ── v0.86.1 ───────────────────────────────────────────────
// IDOL: 서사가 무대를 치렀는데 버튼이 안 눌리면 보수도 없이 펑크가 났다 (실기 제보).
// night_req와 같은 규약의 stage_req — 보조 AI가 켜면 stage_auto/live_auto 이벤트가
// ck_stage/ck_live를 대신 굴려 등급대로 정산한다. 서사가 말한 금액은 여전히 무시
// (경제는 판정이 센다). perform/live_show가 깃발을 지워 이중 정산 차단,
// stage_req_clear가 무대 없는 날의 헛깃발을 내린다.
//
// ── v0.86.0 ───────────────────────────────────────────────
// IDOL 콘텐츠 대형 패치 (실기 요청 5건):
// ① 레슨 개편 — 3스탯 × 4등급(초·중·고·최상급) 12종 생성(LESSON_*). 하루 두 칸
//   (day_slots, 🌙가 되돌림)을 먹고 굴림이 대성공/성공/아쉬움/대실패를 가른다.
//   등급은 유닛 스탯 합이 열고 멤버별 상한(40/60/80/100)이 막는다. 기존 돈-직행
//   항목은 "특별 과외"로 남김.
// ② 팬서비스 탭 — 악수회/사진회/사인회/미니 라이브/팬미팅. 팬·개별 인기·유대를 사고
//   체력을 치른다. 미니 라이브·팬미팅은 굿즈 현장 판매 수입.
// ③ 굿즈 제작 — 포토카드/응원봉/화보집 (goods 목록, 장부에 표시). 라이브 물판이
//   종류 수만큼 커진다 (만석 35+6n% · 성공 18+4n%, funds 짝 유지).
// ④ 음지 2종 — 개인 방송(corrupt 10)·야한 코스튬 촬영(18). 설득 사다리에 끼움.
// ⑤ 일감 백화점 홍보(11/160)·축제 행사(14/420) + 백화점 라이브(13/340/350석).
//
// ── v0.85.9 ───────────────────────────────────────────────
// IDOL 랜덤 이벤트 10종 추가 (실기 요청): 다툼 갈림길(중재/기다림/외면)·냉전,
// 긍정(팬클럽 fans≥800·완주·재방송 aware≥32), 럭키 스케베 2종(해프닝 수위),
// 음지 화보 갈림길(corrupt≥25 — 수위는 암시까지, sunk 규약), 개그 2종.
// 문구는 인원 중립 (DLC 유닛 5인). 효과는 m1/m2/m3 삼중 패턴 — DLC가 m4/m5 자동 복제.
//
// ── v0.85.8 ───────────────────────────────────────────────
// ① 갈림길 블록에 발동 문구(notify)를 부제로 다시 보여준다 — 알림은 그 턴에 흘러가
//   버려서 "무엇에 대한 선택인지" 안 보였다 (실기 제보: 일감 제안을 빚 얘기로 오해).
// ② IDOL 일상 랜덤 이벤트 7종 추가 — 게이트 없는 이벤트가 편지·감기 둘뿐이라 일감을
//   잡고 있는 동안 감기만 반복됐다. 길고양이/조공/소음 민원/장비 고장/선배 방문/
//   바이럴 클립/궂은 날씨(weather 연동). 감기 쿨다운 5→8.
//
// ── v0.85.7 ───────────────────────────────────────────────
// IDOL 프로덕션 탭 머리에 날짜·시간대·계절·날씨. 날짜는 노출 파생 'date' 한 줄
// (연·월·일을 따로 얹으면 다섯 줄로 갈라진다 — 실기 제보). 형식 YYYY-MM-DD.
// 계절은 달력 내장 노출값(season) 그대로. 시간대(tod)·날씨(weather)는 서사가 정하는
// 값이라 enum + allow — 🌙/night_auto가 시간대를 아침으로 되돌린다.
//
// ── v0.85.6 ───────────────────────────────────────────────
// IDOL: 서사가 밤을 넘겼는데 🌙을 안 누르면 날짜가 안 흘러 어긋나는 실사고.
// 하루 정산을 IDOL_DAY_EFFECTS 한 벌로 빼고, 보조 AI가 켜는 night_req 깃발을
// night_auto 이벤트가 같은 한 벌로 소화한다 — 시계 입구는 여전히 하나.
// 🌙 효과가 깃발을 같이 지워 같은 밤이 두 번 흐르지 않는다 (전송→출력 순서 이용).
// 메인 모델에는 [시간] 지시문 — 하루 단위 진행, "며칠 뒤" 다일 도약 금지 (사고 원인).
//
// ── v0.85.5 ───────────────────────────────────────────────
// IDOL 템플릿: 업무·라이브가 잡혀 있는 동안 지시문이 보수({job_pay}·{live_pay}만원)를
// 못 박는다. 모델이 상태를 안 보고 금액을 지어내는 실사고(거리 홍보 120만원을
// "5만 엔"으로 부름) — 자금은 allow에 없어 장부는 안 틀어지지만 몰입이 깨진다.
// 화폐 단위(만원)도 지시문에 명시.
//
// ── v0.85.4 ───────────────────────────────────────────────
// 패널에서 레슨을 찍어도 채팅 속 상태창은 옛 숫자였다 — 상태창은 리수가 그 메시지를
// 다시 그릴 때만 갱신되기 때문 (값 자체는 즉시 적용·저장되고 있었다. 표시 지연일 뿐).
// mainDom(클릭 조작 권한)이 열려 있으면 상태창 루트(id=simst-<uid>, 규칙 #4 uid 섞음)를
// 찾아 본체를 제자리에서 새로 그린다 — 쓰기는 SafeElement가 새니타이즈. 반영을 되읽어
// 확인하고, 안 되는 환경(권한 거부 등)이면 패널 공지에 "다음 메시지에서 갱신"을 붙인다.
// 편성·레슨·달력·변수 수동 보정·프리셋 모두 같은 길을 탄다.
// [live-test] SafeElement innerHTML 대입 반영 여부 웹리스 확인.
//
// ── v0.85.3 ───────────────────────────────────────────────
// 잠긴 액션의 이유가 '조건 미충족' 넉 자뿐이라 유저가 왜 잠겼는지 알 수 없었다
// (실사고: 업무가 잡혀 있어 거리 홍보가 잠긴 것을 리얼리티 난이도 설정 미스로 오해 —
//  거리 홍보의 조건은 난이도와 무관하다: 잡힌 업무 == '없음' 그리고 활동 중단 아님).
// 변수 id를 라벨로 치환해 조건을 그대로 보여준다 (humanCond) — 패널 칩 툴팁·클릭 공지·
// 호스트 알림·상태창 범례가 같은 문구를 쓴다 (currentActionStates 한 곳에서 만든다).
//
// ── v0.85.2 ───────────────────────────────────────────────
// 새 시작 프리셋이 **새 채팅에서 증발**하던 문제 (실사고: 리얼리티를 골랐는데 새 채팅이
// 10레벨·팬 200명 초기값으로 시작). 프리셋은 고른 순간의 채팅 상태에만 적용됐는데,
// 새 채팅은 세션을 초기값으로 새로 잡는다 — "새 채팅을 시작하기 전에 고르세요"라는
// 안내와 구조가 모순이었다. 선택을 캐릭터에 저장(sim:start-preset:<캐릭터>)하고,
// 턴 0인 세션이 잡힐 때마다 자동 적용한다 (첫 턴 뒤엔 스냅샷이 이긴다). 패널의 프리셋
// 버튼에 ✓ 표시 — 새 채팅마다 무엇으로 시작하는지 보인다. 없는 id는 조용히 무시.
//
// ── v0.85.1 ───────────────────────────────────────────────
// 더티 배너의 [지금 적용]이 안 먹히는 것처럼 보이던 문제.
// ① setCharacter 직후의 getCharacter가 아직 옛 캐릭터를 줄 수 있다 — 그러면 방금 쓴
//    스키마 대신 옛 것이 다시 로드되고 배너가 "미반영"으로 되그려진다. 설치 후 되읽기가
//    쓴 것과 일치하는지 확인하고 불일치면 350ms 간격 3회 재시도.
//    ([캐릭터에 적용]은 같은 코드인데 "됐다"는 신고는 시차다 — 나중에 누르면 정착돼 있다)
// ② 성공하면 배너가 흔적 없이 사라져 확인이 없었다 — "✓ 캐릭터에 적용됐어요" 한 줄을
//    3.5초 남긴다.
// ③ 덤으로 찾은 실버그: 새 시작 프리셋이 out 스냅샷을 저장하지 않아 메모리에만 남았다 —
//    채팅을 옮겼다 돌아오면 프리셋이 조용히 증발. 변수 수동 보정과 같은 규약으로 저장.
//
// ── v0.85 ─────────────────────────────────────────────────
// 아이돌 템플릿 — 난이도 시스템 + 관리 시설 + 빚 독촉.
// ① 난이도(hard: 쉬움/보통/어려움/리얼리티) — 원칙대로 "문턱을 미는" 변수 하나.
//    이자율 3/5/7/9% · 팬 획득 ×1.2/1.0/0.8/0.6 · 영업 보정 +2/0/-2/-4 · 시설 비용
//    ×0.75/1.0/1.25/1.5 · 독촉 문턱 3600/3000/2400/1800. **보통 = v0.84까지의 숫자와
//    전부 일치**라 기존 세이브가 안 흔들린다.
// ② 관리 시설 — 회식·마사지샵·스파·리조트 (편성표 [관리] 탭, 쉬기·이야기도 이사).
//    위 시설일수록 세게 돌려주고 인지도가 연다(32=D·46=C·76=A — 등급 눈금).
//    비용은 파생(*_cost)이라 조건·지출·상태창이 같은 줄을 읽는다.
// ③ 빚 독촉(collector) — 문턱 넘은 빚에 정장 둘이 찾아온다. 소개받은 일(타락도 +8,
//    음지 탭이 열리는 문) / 긁어모아 막기 / 버티기(빚 이자 가산 + 멘탈).
// ④ DLC 프리셋 = 신규 데뷔 × 난이도 4종 — 전원 인지도·화제성·팬·판매 0, 능력치 1레벨.
//    다른 건 자금·빚과 hard뿐. 실측(60일 8시드): 깨끗한 플레이 8/8·8/8·8/8·3/8,
//    빚 상환+음지 병행 시 리얼리티 6/8 — "관리 못 하면 음지로 밀린다"가 구조로 성립.
// 규칙 #5 확인 — 새 지적 0건, mid+high 34→32 (독촉 덕에 "아무것도 안 해도 전부
// 생존"[긴장 없음] mid가 내장·DLC 양쪽에서 해소).
//
// ── v0.84.1 ───────────────────────────────────────────────
// 게임 패널의 잠긴 액션을 누르면 차단 이유를 Risuai.alert로 알렸는데, 알림이 우리
// 전체화면 iframe **뒤에** 떠서 문구가 안 보였다 (규칙 #6의 alert판 — alertConfirm만
// 조심하고 alert는 놓쳤다). 패널이 떠 있으면 패널 안 공지줄(gameNotice)로, 아니면
// 기존대로 호스트 알림. 나머지 alert 호출처 전수 감사 — 패널 닫힌 문맥(제안 칩·갈림길
// 히트테스트·조작줄)이거나, 패널 열기 전 조기 반환이거나, 먼저 패널을 닫는 규약 준수 확인.
//
// ── v0.84 ─────────────────────────────────────────────────
// ① 상태창 탭을 누르면 리수 화면 전체가 밀리던 사고 수정.
//    숨김 라디오가 `position:absolute` 0×0이었는데, 라벨 클릭 때 브라우저가 라디오에
//    포커스를 주며 scrollIntoView를 한다 — 리수의 overflow:hidden 앱 컨테이너까지
//    스크롤되어 화면이 밀리고(아래는 검은 여백) 스크롤바가 없어 되돌릴 수도 없었다.
//    `display:none`으로 교체 (렌더 안 되는 요소는 포커스 자체가 불가능하다). 기본 탭·
//    다중 패널 뼈대·AI 커스텀 상태창 지침 세 자리 모두. (규칙 #7로 기록)
// ② 아이돌 템플릿 — 비너스 배틀 (라이브 배틀 순위 결전).
//    순위표가 곧 대진표: 위로 갈수록 상대가 세진다(v_vs). 참가비만 내면 도전은 열리고,
//    이기면 상금·팬·순위, 지면 멘탈·순위를 잃는다. 정점(1위)은 판을 끝내지 않는 승리.
//    실측 곡선 — 초반엔 50위 벽, 중반 20위 벽, 후반 정점 다툼(1위 방어 36%), 만렙 군림(87%).
// ③ 아이돌 DLC — 세계관 지시문. `when: '1'` 지시문은 매 턴 주입되므로 봇 설명 없이도
//    스키마가 세계의 전제(아이돌 지상주의 + 비너스 배틀)를 직접 깔아 준다.
// ④ 진단 오탐 둘 (비너스가 드러냄, 규칙 #5 확인 완료 — 새 지적 0건, mid+high 34 유지):
//    · 설정 의존 — `not unit_over`처럼 시작값이 이미 만족시키는 항을 게이트로 오인 (극성 확인 추가)
//    · 편성 게이트 액션의 **판정**이 쓰는 변수(v_rank)를 '안 움직임'으로 신고 (문 상속 추가)
//
// ── v0.83.3 ────────────────────────────────────────────────
// 진단이 **정상 설계를 벌주던** 두 자리 (v0.52 원칙 — 그런 도구는 아무도 안 쓴다).
//
// ① 팝업으로만 오르는 값에 걸린 문턱을 "못 쓰는 액션/죽은 이벤트"로 신고했다.
//    편성 슬롯은 이미 봐 주고 있었는데 **업그레이드 항목**(레슨·하이드아웃 시설)은 안 봤다.
//    던전러너의 의상 해금 다섯이 통째로 mid 오탐이었고(`st_tailor >= N` — 재봉소는 팝업에서만
//    올린다), 아이돌 DLC의 대관 문턱(`u_pow >= N` — 레슨 합)도 같은 자리였다.
//    이제 파생을 타고 넘어간다: 항이 **전부** 팝업 전용이면 그 파생도 팝업 전용이다.
//    ⚠ '유일한 출처'가 핵심 — 포인트 변수(자금)는 items 비용으로도 빠지지만 액션·이벤트가
//      숱하게 움직이므로 여기 넣으면 `funds >= N` 조건이 전부 면죄부를 받는다.
//      프리셋('새 시작')은 시작값만 정하므로 런타임 출처로 안 친다.
// ② 조건 하나하나는 닿았는데 **동시에** 안 맞은 액션을 "못 쓰는 액션"(high)이라 했다.
//    자금이 찼을 땐 이름값이 모자라고 이름값이 찼을 땐 자금을 다 쓴 흐름 문제라, 문턱을
//    내리라는 처방이 엉뚱하다. 실측으로 두 번 밟았다(시민회관·케이블 음악방송).
//    '조건 동시 불충족'(mid)으로 갈라 이유를 그대로 말한다.
//
// 규칙 #5대로 내장 16종 + 생성기 산출물 2종에 돌려 확인: **새로 생긴 지적 0건**,
// mid+high 40 → 34 (전부 위 두 부류의 오탐 제거).
//
// ── v0.83.2 ────────────────────────────────────────────────
// 초상이 하나도 안 뜨는 사고 — **이름 안에 점이 있는 에셋**(Nakano_Miku.default.avif)에서
// 짝짓기가 실패했다. 꼬리 하나를 떼는 규칙(`\.[a-z0-9]+$`)이 'Nakano_Miku.default'에서
// `.default`를 확장자로 착각해 'Nakano_Miku'까지 깎아 버린다 — 오류도 안 나고 얼굴만 안 뜬다.
// 규칙을 core/party.js의 matchAssetName 하나로 옮기고("떼고/안 떼고" 네 조합을 다 맞춰 본다)
// 테스트로 못 박았다. 어댑터는 그걸 부르기만 한다.
//
// ── v0.83.1 ────────────────────────────────────────────────
// 초상 매핑에 대조를 붙였다. 명단 44명에 캐릭터 에셋 49개면 **어느 쪽이 남는지**가 안 보인다 —
// 실제 제보가 "5명 누락인가?"였고, 답은 인물마다 눈으로 맞춰 보는 것 말고는 없었다.
// [🔎 에셋 이름 불러오기 · 대조]가 세 갈래로 짚는다:
//   · 초상 없음 — 명단에 있는데 매핑이 빈 인물
//   · 에셋에 없는 이름 — 매핑은 했는데 그런 에셋이 없다(오타·모듈 전용)
//   · 안 쓰인 에셋 — 읽히긴 했는데 아무도 안 쓰는 그림(명단에서 빠진 인물이 여기 뜬다)
// 확장자는 양쪽에서 떼고 본다 — 리수 버전마다 붙기도 하고 안 붙기도 한다.
//
// ── v0.83.0 ────────────────────────────────────────────────
// [에셋 목록 불러오기]가 몇 초씩 멈춘다는 제보. 원인이 둘이었고 둘 다 얻는 게 없었다.
//
// - **무인자 getDatabase() 폴백 제거.** includeOnly를 모르는 옛 리수 대비로 넣어 둔
//   사다리 마지막 칸인데, 인자 없이 부르면 리수 DB를 통째로 샌드박스 브리지 너머로
//   직렬화해 넘겨받는다 — 캐릭터·채팅·로어북이 다 실린다. 그걸 받아서 하는 일은
//   modules 배열 하나 꺼내는 것뿐이다. 값을 못 치를 비용이라 뺐다.
// - **모듈 에셋 읽기를 기본 꺼짐으로.** 새 인자 `module_assets`(off/on).
//   v0.54.3~6에서 모듈봇(MIKU&BRS)을 위해 낸 길인데, 그 뒤로도 "이 리수 빌드는 db가
//   잠겨 있어 못 읽는다"가 계속 나왔다(v0.54.6 주석). 대부분의 판에서 이 경로는
//   **느리기만 하고 아무것도 못 읽는다.** 이미지가 모듈에 사는 봇만 켜서 쓰면 된다.
//   끈 상태에서는 db를 아예 안 건드리므로 매 턴 이미지 해석 경로도 같이 가벼워진다.
//
// ⚠ 끈 상태의 실존 대조는 **캐릭터 에셋만** 본다. 이미지가 모듈에 있는 봇에서 켜지 않으면
//   그 조합이 "실존하지 않음"으로 걸려 이미지가 안 나갈 수 있다 — 편집기의 에셋 안내가
//   그 사실과 켜는 법을 같이 말한다. 팩의 verify:false도 그대로 유효한 탈출구다.
//
// ── v0.82.1 ────────────────────────────────────────────────
// 유닛 랭크가 **시작하자마자 S**였다. u_pow는 셋을 자리 배수로 더한 값이라 만점이 990인데
// 문턱을 한 사람 기준(260/200/150/100/60)으로 잡아 뒀다 — 시작 u_pow 266이 그대로 S다.
// 랭크가 첫 턴에 천장이면 성장이 화면에 안 보이고, u_pow를 문턱으로 쓰는 대관(합동 페스티벌
// 이상)도 첫날에 전부 열린다. 만점 대비 비율로 다시 잡았다 (800/620/450/300/180, 시작은 D).
// 대관의 u_pow 문턱도 같은 자로 옮겼다 (300/450/620).
// 자리 수가 다른 봇으로 개조할 때 같은 함정을 다시 밟으므로 test-idol에 눈금 검사를 넣었다.
//
// ── v0.82.0 ────────────────────────────────────────────────
// 아이돌 프로듀스 — **진짜 프로듀서**로. 누르면 되는 판에서 고르는 판으로 바꿨다.
//
// - [일감] 버튼 두 개가 등급을 보고 알아서 자리를 골라 주던 것을 **사다리 일곱**으로 폈다.
//   거리 홍보 → 지역 라디오 → 잡지 화보 → 지방 방송국 → 케이블 → 지상파 → 골든타임 특집.
//   자리마다 여는 문턱(인지도)·영업비·성사율이 다르고, 헛걸음이어도 영업비는 나간다.
//   ⚠ 여는 축은 **인지도 하나**다. 등급은 인지도가 문턱을 넘을 때 따라 오르는 값이라
//   `rank_n >= 4`를 같이 걸면 같은 말이 두 번 되고, 진단이 이걸 "못 쓰는 액션"으로 오해해
//   high 지적 세 건을 만들었다.
// - [성사율] 굴리기 전에 확률이 보인다 (일감 탭). 20면 주사위라 눈 하나가 5%p고, 대성공이
//   늘 있으니 바닥 5%·천장 100%다. ⚠ 보정에 **상한 20**을 뒀다 — 캡이 없으면 인지도 90쯤부터
//   여섯 자리가 전부 100%가 되어 판정이 장식이 된다. 펑크는 캡 밖에서 깎아 늘 아프게 뒀다.
//   신인 75/60/45/40/10/5 → 정상 100/100/100/100/85/65 (펑크 3회면 골든타임 35%).
// - [영업 판정 여섯] 엔진은 **판정을 액션 효과보다 먼저** 굴린다 — 판정은 "어느 자리를
//   노렸나"를 알 수 없다. 그래서 판정은 이겼는지만 pitch_won에 적고 **자리를 넣는 건 액션**이
//   한다. 대어(20)면 한 칸 위를 물고 온다. 같은 이유로 음지 설득도 자리마다 하나씩이다.
// - [무대] 라이브는 **빌리는 것**이라 판정이 없다. 대신 대관료가 선불이고 정원이 천장이라,
//   못 채우면 그대로 손해다 — "잡을 수 있는가"와 "채울 수 있는가"가 다른 질문이라는 게
//   이 축의 전부다. 예상 객석(live_fill)이 그 답이고 60% 아래면 붉게 뜬다.
//   라이브하우스 → 시민회관 → 합동 페스티벌 → 단독 공연 → 전국 투어 (팬 수·유닛 종합이 연다).
// - [제작] 의상 3단계·음반 3단계. 위로 갈수록 비싸고 **이름값을 요구한다** — 무명 유닛에는
//   좋은 사람이 안 붙는다. 음반은 한 단계씩만 올라가고, 한 번 내면 월말마다 인세가 들어온다
//   (이 판에서 손을 놓아도 도는 유일한 돈).
// - [음지] 타락도 + 네 자리(심야 행사 → 스폰서 자리 → 수위 화보 → 성인 영상). 넷 다 그날 밤에
//   끝나고(급전이라 일정표에 안 올린다), **셋이 거절할 수 있다** — 타락도가 오를수록 거절이
//   줄고 문턱도 열린다. 거절도 값을 치른다(호감·멘탈). 탭 자체가 `funds < 250 or corrupt >= 1`
//   일 때만 보인다. **갈림길**: 타락도 45를 넘으면 지상파가, 25를 넘으면 골든타임이 닫힌다.
//   이게 없으면 음지는 그냥 "돈 더 주는 버튼"이라 갈림길이 안 된다.
// - [끝나는 길] 셋으로. 번아웃(멘탈 0) · **미납 이탈(월급 석 달)** · 파산. ⚠ 미납을 두 달로
//   뒀더니 정상 플레이가 8/8 전멸했다 — 이 판은 자금이 늘 0 근처를 걷기 때문에 한두 번
//   미끄러지는 건 예사다. 석 달은 사정이 아니라 못 하는 것이다.
// - [고정비] 사무소 임대료(월말) 신설. 융자는 **이미 진 빚에 비례해** 얹힌다
//   (1200 → 1880 → 2668 → 3535) — 정액이던 시절엔 돌려막기가 영원해서 파산이 한 번도 안 떴다.
//
// 밸런스에서 배운 것: 진단의 "아무것도 안 해도 전부 생존"을 잡으려 임대료를 200으로 올렸더니
// 정상 플레이 생존율이 38%까지 떨어졌다. 진단이 굴리는 방치는 이 템플릿에서 도달할 수 없는
// 상태다(시간이 🌙로만 흐르는데 방치 시뮬은 날짜를 공짜로 넘긴다). 지표에 맞추다 판을 망칠
// 뻔했고, 되돌렸다. 남은 mid 두 건은 v0.81에도 있던 것이다.
//
// 잡은 버그: 급작 제안 갈림길이 job에 '지역 라이브'(라이브 쪽 값)를 넣고 있었다 — enum에 없는
// 값이라 난이도·보수 표가 전부 0으로 떨어져 **공짜로 치르는 무대**가 됐다. 표현식 안의 문자열은
// 검증이 못 보니, 축이 둘인 스키마에서는 눈으로 짝을 맞출 것.
//
// ── v0.81.0 ────────────────────────────────────────────────
// 아이돌 프로듀스 템플릿 개편 — 실기 피드백 넷.
//
// - [탭] **프로덕션 + 유닛 결합.** 이 판은 사무소에 유닛이 하나뿐인데 갈라 둬서
//   "우리가 어디까지 왔나"를 두 탭을 오가며 봐야 했다. 유닛을 여럿 굴리는 봇으로 개조할
//   때 다시 쪼개면 된다 (유닛마다 탭 하나).
// - [유닛] 랭크·인기도·보유곡·보유의상 추가. 랭크는 종합 능력치의 파생이고, 인기도는
//   소속 전원의 개별 인기 합이다(무대에 안 선 멤버의 팬도 유닛의 팬이다). 곡·의상 이름은
//   시스템이 못 지으므로 목록 변수 + 보조 AI에게 개방 — "무엇이 나올 차례인가"까지만 시스템.
// - [일감] **의뢰판으로.** 업무(job)와 라이브(live)를 **동시에 하나씩** 들 수 있는 두 축으로
//   쪼갰다 — 예전엔 칸이 하나라 "다음 주 라이브 전에 화보를 끼울까"가 성립하지 않았다.
//   각각 일정·난이도·보수가 뜨고, 라이브에는 예상 티켓(정원이 천장)이 붙는다. 그 다음 차례는
//   job_queue·live_queue 목록이 "@+N" 규약으로 들고 달력에 그대로 뜬다.
//   라이브 판정(ck_live) 신설 — 티켓·굿즈 수입이 여기서만 들어온다.
// - [장부] 수입을 갈래 넷(무대·티켓·굿즈·음반)으로 나누고 **총합 income을 파생으로** 돌렸다.
//   갈래를 늘려도 장부가 저절로 맞는다 (예전엔 income에도 같이 적어야 했고 빠지면 지출이
//   부풀었다). 멤버 월급을 지출로 신설 — 등급이 오르면 같이 오른다.
//
// 진단으로 고른 값 둘 (mid 지적 3건 → 1건):
//   · 월급 배수 90 — 45면 "아무것도 안 해도 전부 생존", 140이면 "액션을 쓸수록 빨리 죽는다".
//     90에서만 파산 이벤트가 살아나고 난이도 지적이 사라진다.
//   · 홍보 체력 3·쿨다운 3 — 월급이 자금을 조이자 6·2가 함정 액션으로 드러났다(빼면 33턴 더 삶).
// 남은 mid 1건(프리셋 수명 수렴, 150턴)은 개편 전부터 있던 것이다. 팬 14,000명인 유닛이
// 신인보다 빨리 죽는 게 더 이상해서 억지로 안 맞췄다.
//
// 잡은 버그: 음반 수입을 장부에만 적고 자금에 안 넣어 **유령 지출**이 생기던 것 (지출은
// 수입 − 잔고차이로 역산하므로, 안 들어온 돈이 그대로 "쓴 돈"이 된다). test-idol이 잡았다.
//
// ── v0.80.0 ────────────────────────────────────────────────
// 실기 제보 두 건 — 둘 다 "판마다 달라야 할 것이 안 달라진다".
//
// - [시간] **시작 시각 무작위** (`time.startRandom`). 배포된 봇은 새 채팅마다 늘 같은 날
//   같은 시각에서 시작한다. 그걸 바꾸려면 플레이어가 시간 탭을 열어야 하는데, 그건 설정을
//   만질 줄 아는 사람만 쓰는 기능이 된다. 시각·분·일·월·년을 칸마다 [최소, 최대]로 정하고,
//   **채운 칸만** 굴린다 (비운 칸은 start 그대로 — "시각만 무작위, 날짜는 고정"이 가장 흔하다).
//   시드는 chatId라 **같은 판에서는 고정**(리롤에 안 흔들림), 새 채팅이면 새로 굴린다.
//   판 초기화만 예외로 즉석 난수를 쓴다 — chatId 시드면 초기화해도 같은 시각이 나온다.
//   rng를 안 주는 호출자(진단·테스트)는 예전 그대로 start — 결정적 경로를 안 흔든다.
//   없는 날짜(2월 31일 등)는 그 달 말일로 당긴다. flat30에서 31일 범위는 경고.
// - [규칙] **리롤 안정 난수 토글**. 배선(`rerollStableRng`)은 v0.1부터 있었는데 편집기 칸이
//   없어서 끌 방법이 JSON 손편집뿐이었다 — 규칙 #3의 세 번째 재발이다. "리롤해도 변수가
//   똑같다"는 제보가 정확히 이 자리였다. 검증도 없어 오타(`rerollStable: false`)가 조용히
//   무시됐으므로 타입 검사도 같이 넣었다. 기본은 켜짐 유지 (판정의 완벽 주사위가 이것에 기댄다).
//
// ── v0.79.0 ────────────────────────────────────────────────
// 지적 접기 — 한 종류의 지적이 인원수만큼 쏟아져 정작 급한 오류를 덮던 문제.
//
// 실측 제보: 145명 명단을 두 팩에 넣자 "인물 'X'는 팩 Y가 먼저 담당합니다"가 **145줄**.
// 낱말 겹침 경고가 147줄 쏟아졌던 v0.44.1과 같은 병이라 처방도 같다 — 묶어서 한 줄.
// 두 층에서 막는다: 검증기가 원인 단위로 묶고, 화면은 어떤 검사가 터지든 넘치지 않게 접는다.
//
// - [검증] 에셋 팩 겹침을 **가려진 팩마다 한 줄**로 (인물마다 한 줄 → 팩마다 한 줄).
//   몇 명인지 + 앞 세 명 + "이 팩은 그 인물들에게 안 쓰입니다"까지 한 문장에 담는다.
//   한 명만 겹치면 예전 문장 그대로 (묶을 게 없으면 묶은 티를 내지 않는다).
//   when 게이트가 다른 팩은 여전히 무경고 (성인/임신 팩 패턴 — v0.52 원칙 유지).
// - [패널] 오류·경고 목록을 앞 6줄만 펼치고 나머지는 `N줄 더 보기`로 접는다.
//   8줄 이하는 그대로 둔다 — 접는 값이 접히는 값보다 크면 안 된다.
//   지적 본문에 escapeText도 같이 걸었다 (경로·메시지가 그대로 innerHTML에 들어가고 있었다).
//
// ── v0.78.0 ────────────────────────────────────────────────
// 편집 동선 두 군데 — 둘 다 "기능은 있는데 그 자리에 없어서 없는 것처럼 보이던" 것이다.
//
// - [편집기] **생성 모델 선택을 생성 버튼이 있는 곳마다** (buildGenModelRow로 추출).
//   설정 자체는 전역이라 에셋 팩 변환·상태창 꾸미기에도 이미 적용되고 있었는데, 고르는
//   자리가 [AI 어시스턴트] 탭 안에만 있어서 "에셋 변환은 무조건 보조 모델"로 보였다
//   (실기 제보). 이제 에셋 임포터와 꾸미기 컨트롤에도 같은 줄이 뜨고, 그 화면에서 처음
//   열어도 선택값을 읽어 온다 (예전엔 AI 탭을 거쳐야 aiGenModel이 채워졌다).
// - [패널] **더티 배너에 [💾 지금 적용]** — 예전엔 적용 버튼이 [편집 작업공간] 전용이라
//   한 칸 고칠 때마다 페이지를 옮겨야 했다. 배너는 이미 "반영 안 됨"을 알고 그 자리에
//   떠 있으니 거기서 끝내는 게 맞다. 설치 로직은 runInstall 한 벌로 합쳤고, 보고는
//   배너 자기 칸에 쓴다 (편집 도구 화면에는 #sc-schema-report가 없다 — 작업공간 노드다).
//   성공하면 renderPanel이 배너를 걷어 가는 것이 곧 완료 신호다.
//
// ── v0.77.0 ────────────────────────────────────────────────
// 지도 규격 — 배치 규격서(꾸미기 [배치까지])가 지도·도해 패턴을 가르친다.
//
// 소전봇(Frontline Crawler 1.5) 카드 분석의 결론을 규격서에 옮겼다. 저쪽 기법:
// 루아 0줄, 지역×세력 투명 PNG 68장 겹치기 + 모델이 매 턴 "drazni_usro" 토큰 재출력.
// 우리는 렌더 능력이 v0.76으로 이미 다 있었다 — 남은 건 그 기법을 AI가 모른다는 것과,
// 규격서 스스로 `position: absolute`를 금지하고 있었다는 것 (지도의 핵심 기법이 금지어).
//
// - [규격서] 배치 프롬프트만 absolute 해제 — relative 컨테이너 내부 한정. 스킨 프롬프트
//   (CSS만, 마크업 통제 불가)는 금지 유지.
// - [규격서] 자리표시자 심화 절: 수식·조건부 클래스(`class="pin {식 ? 'a' : ''}"`),
//   CBS 이미지({{img::이름}} 두 겹 보존), 이름 조립({{img::지역A_{region_a}}}).
//   에셋 이름 지어내기 금지 — 요청 문구에 적힌 이름만.
// - [규격서] 지도·도해 패턴 절: 지점 핀(absolute % 좌표 + translate 중심 보정) /
//   영역 색칠(inset:0 투명 레이어 겹치기 + 변수 조립) / 접이식은 체크박스 + {uid}.
// - [편집기] 배치 요청 칸 안내문에 지도 예시 한 줄 (발견 가능성).
// - 상태 관리가 소전봇과 갈리는 지점: 저쪽은 모델이 지도 토큰 12개를 매 턴 재출력(리롤·
//   누락에 취약), 우리는 enum 변수를 보조가 굴리고 스냅샷이 지킨다 — 지도 갱신 = 변수 갱신.
// - 지도 전용 편집기 섹션(클릭으로 핀 찍기)은 보류 그대로 — 이번 건 규격서·문법 층만.
// test-mapdoc.js 신설 (규격서 배선 9종 + 전황판 실전 왕복 6종).
//
// ── v0.76.0 ────────────────────────────────────────────────
// 템플릿 안의 리수 CBS(`{{...}}`)를 건드리지 않는다 — 손상 1건 + 설치 거부 1건.
//
// "소전봇 같은 작전 지도를 상태창으로 만들 수 있나"를 실측하다 나온 결함이다.
// 지도는 이미 오늘 가능했다(배경 이미지 + 좌표 절대배치 핀 + 조건부 클래스, 전부 template
// 모드로 표현 가능). 막고 있던 건 배경을 부르는 `{{img::지도}}` 한 줄이었다.
//
// - [손상] 우리 치환 정규식 `/\{([^{}]+)\}/`이 CBS 안쪽 한 겹을 문다. 이름이 변수·시간
//   노출 이름과 겹치면 값이 들어가 CBS가 깨졌다 — 실측 `{{date}}` → `{3월 12일}`
//   (`date`는 시간 체계가 노출하는 이름이다). 안 겹치는 이름은 evaluate가 던져 우연히
//   살아남고 있었을 뿐이라, 이름 운에 맡기던 상태였다.
// - [설치 거부] 검증기 checkTemplateRefs는 같은 자리에서 하드 오류를 냈다. `{{img::지도}}`
//   하나만 있어도 스키마가 설치되지 않았다 — 렌더는 멀쩡한데 문 앞에서 막힌 셈.
// - 수정: 양쪽 다 "바깥에 중괄호가 한 겹 더 있으면 우리 것이 아니다"로 건너뛴다.
//   렌더와 검증이 같은 기준을 쓰므로 어긋날 자리가 없다. 진짜 오타(`{ghost_var}`)는 그대로 오류.
// test-cbspass.js 신설 — 실제 작전 지도 템플릿을 검증→렌더까지 왕복시킨다.
//
// ── v0.75.0 ────────────────────────────────────────────────
// 에셋 aux 지시가 인물별 칸 구조를 잃던 버그 — "에셋은 종류와 형식이 조금만 복잡해지면
// 거의 안 돌아간다"(이용자 제보)의 원인. 유저 실측 확인: **main 모드는 잘 됐고 aux만 문제.**
//
// 원인: auxImageSpec이 열린 팩 전부를 평평한 하나로 뭉갰다 — 칸 id 합집합·값 합집합에
// "어느 칸이 어느 인물 것인지"가 없다. 해소기(routePack→composeName)는 철저히 팩 단위라,
// 팩이 하나면 합집합=그 팩이라 정확하지만 둘부터 지시가 거짓말이 된다. 보조가 가장
// 자연스럽게 하는 행동(그 인물에 어울리는 칸만 채우기)이 그 인물 팩의 필수 칸을 빠뜨리고
// → composeName null → 폴백 사다리도 못 구제(빠진 필수 칸은 대상 아님) → **이미지 실종**.
// 같은 파일의 main 주입문은 팩별 구조를 이미 다 적고 있었다 — 기본값 aux가 정보가 더 적었다.
//
// - [코어] auxImageSpec: 인물별 줄로 쪼갠다. 구조는 **라우팅되는 팩**이 정하고(composeName이
//   그 팩의 칸만 읽는다), 어휘는 그 인물을 담당하는 열린 팩들의 합집합 — values는 강제가
//   아니라 실존 대조로만 걸리므로 게이트 팩이 어휘를 넓히는 설계가 그대로 산다.
//   구조가 같은 인물은 한 줄로 묶어 줄 수 = 팩 수 (인물이 26명이어도 안 는다).
//   optional 표시 + "빠뜨리면 이미지가 사라진다" 경고. 팩 id는 여전히 안 낸다.
//   **팩이 하나면 예전 평평한 형태 그대로** — 대다수 봇 무회귀. aux_flow도 같이 적용.
// - [검증] 필수 칸에 fallback이 없으면 경고 — 보조가 빠뜨렸을 때의 마지막 방어선이다
//   (템플릿 16종 오탐 0). 에셋 팩 변환 프롬프트에도 "필수 칸엔 fallback 필수" 규칙 추가.
// test-assets.js에 인물별 구조 어서션 7종 추가.
